import unittest

class Test(unittest.TestCase):
    def test_groups(self):
        result = group_anagrams(['eat','tea','tan','ate','nat','bat'])
        groups_as_sets = sorted([sorted(g) for g in result])
        expected = sorted([sorted(g) for g in [['eat','tea','ate'],['tan','nat'],['bat']]])
        self.assertEqual(groups_as_sets, expected)
    def test_empty(self):
        self.assertEqual(group_anagrams([]), [])
    def test_no_anagrams(self):
        result = group_anagrams(['abc', 'def'])
        self.assertEqual(len(result), 2)

if __name__ == '__main__':
    unittest.main()
